private static String javaCharset(String charset) {
    // Mime recommendation:
    // http://www.iana.org/assignments/character-sets/charset-identifiers.xhtml
    switch (charset) {
        case "utf-8":
            return "UTF-8";
        case "Shift_JIS":
            return "Shift_JIS";
        case "ISO-8859-1":
            // Some Unicode characters have replacement uses in JRE.
            return "latin1";
        case "Windows-1252":
            return "windows-1252";
        // There are many other common without an equivalent except for ASCII which 'A' to 'Z'.
        case "US-ASCII":
            return "US-ASCII";
        default:
            return charset;
    }
}

