private OuterFaceCirculator selectOnOuterFace(final Predicate<Node> predicate, final Node start, final Node stop, final int dir) {
    OuterFaceCirculator result = null;
    if (dir == 0) {
        // Forward search
        Node current = start;
        while (current != stop) {
            if (predicate.test(current)) {
                result = new OuterFaceCirculator(current);
                break;
            }
            current = getNextNode(current);
        }
    } else if (dir == 1) {
        // Backward search
        Node current = stop;
        while (current != start) {
            if (predicate.test(current)) {
                result = new OuterFaceCirculator(current);
                break;
            }
            current = getPreviousNode(current);
        }
    }
    return result;
}

