    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '{' || c == '}') {
            encodedString.append("%"); // Percent-encode '{'
            encodedString.append(c); // Append '{' (or '}')
        } else {
            encodedString.append(c); // Append char as is
        }
    }
    return encodedString.toString();
}

