public void addToClassPath(Vector<URL> cpV, String dir) {
    try {
        File[] dirs = new File(dir).listFiles();
        if (dirs != null) {
            for (File dir : dirs) {
                if (dir.isDirectory()) {
                    cpV.addAll((Vector<URL>) dir.toURI().toURL());
                } else if (dir.isFile()) {
                    cpV.add(dir.toURI().toURL());
                }
            }
        }
    } catch (MalformedURLException e) {
        // handle the exception appropriately
        e.printStackTrace();
    }
}

