private static char decodeHexNibble(final char c){
    if (c >= '0' && c <= '9') {
        return (char) (c - 48);
    } else if (c >= 'A' && c <= 'F') {
        return (char) (c - 55);
    } else if (c >= 'a' && c <= 'f') {
        return (char) (c - 87);
    } else {
        return Character.MAX_VALUE;
    }
}

